<div class="card"><div class="card-header"><h3 class="card-title"><i class="ti ti-files me-2"></i>Daftar template</h3><div class="card-actions text-secondary small">Template sistem boleh diedit atau dinonaktifkan, tetapi tidak dihapus.</div></div><div class="table-responsive"><table class="table table-vcenter card-table"><thead><tr><th>Template</th><th>Kategori</th><th>Isi</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody>
<?php if(empty($templates)):?><tr><td colspan="5" class="text-center py-5 text-secondary">Belum ada template pesan.</td></tr><?php endif?>
<?php foreach($templates as $t):$system=in_array($t['template_code'],['member_registration_received','member_registration_approved','loan_request_status','loan_due_reminder','loan_overdue'],true);?><tr><td><div class="fw-semibold"><?=html_escape($t['name'])?></div><div class="text-secondary small"><code><?=html_escape($t['template_code'])?></code><?= $system?' · <span class="badge bg-blue-lt text-blue">Sistem</span>':''?></div></td><td><?=html_escape($categories[$t['category']]??$t['category'])?></td><td class="text-secondary text-wrap" style="min-width:300px"><?=nl2br(html_escape(mb_strimwidth($t['body'],0,240,'…')))?></td><td><span class="badge <?=!empty($t['is_active'])?'bg-green-lt text-green':'bg-secondary-lt text-secondary'?>"><?=!empty($t['is_active'])?'Aktif':'Nonaktif'?></span><div class="text-secondary small mt-1"><?= (int)($t['usage_count']??0)?> pesan tercatat</div></td><td class="text-end text-nowrap"><?php if(!empty($can_edit)):?><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#edit-template-<?= (int)$t['id']?>"><i class="ti ti-edit me-1"></i>Edit</button><?=form_open('wa/templates/action/'.(int)$t['id'],['class'=>'d-inline'])?><input type="hidden" name="action" value="toggle"><button class="btn btn-sm <?=!empty($t['is_active'])?'btn-outline-warning':'btn-outline-success'?>" data-confirm="<?=!empty($t['is_active'])?'Nonaktifkan template ini? Pesan baru tidak akan menggunakannya.':'Aktifkan template ini kembali?'?>" data-confirm-title="Status Template" data-confirm-ok="Ya, Lanjutkan"><i class="ti <?=!empty($t['is_active'])?'ti-player-pause':'ti-player-play'?>"></i><span class="d-none d-xl-inline ms-1"><?=!empty($t['is_active'])?'Nonaktif':'Aktifkan'?></span></button><?=form_close()?><?php endif?><?php if(!empty($can_delete)&&!$system&&(int)($t['usage_count']??0)===0):?><?=form_open('wa/templates/action/'.(int)$t['id'],['class'=>'d-inline'])?><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger" data-confirm="Hapus template ini permanen? Tindakan tidak dapat dibatalkan." data-confirm-title="Hapus Template" data-confirm-ok="Ya, Hapus"><i class="ti ti-trash"></i><span class="d-none d-xl-inline ms-1">Hapus</span></button><?=form_close()?><?php elseif(!empty($can_delete)&&!$system):?><span class="text-secondary small d-inline-block ms-1" title="Sudah dipakai pesan">Riwayat disimpan</span><?php endif?></td></tr>
<?php endforeach?></tbody></table></div></div>
<?php if(!empty($can_edit)):foreach($templates as $t):$system=in_array($t['template_code'],['member_registration_received','member_registration_approved','loan_request_status','loan_due_reminder','loan_overdue'],true);?><div class="modal modal-blur fade" id="edit-template-<?= (int)$t['id']?>" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><?=form_open('wa/templates')?><input type="hidden" name="id" value="<?= (int)$t['id']?>"><div class="modal-header"><h5 class="modal-title">Edit template: <?=html_escape($t['name'])?></h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-5"><label class="form-label">Kode</label><input class="form-control font-monospace" name="template_code" required value="<?=html_escape($t['template_code'])?>" <?=$system?'readonly':''?>><div class="form-hint"><?=$system?'Kode template sistem dikunci agar integrasi tetap bekerja.':'Kode digunakan sebagai identitas template.'?></div></div><div class="col-md-4"><label class="form-label">Nama</label><input class="form-control" name="name" required value="<?=html_escape($t['name'])?>"></div><div class="col-md-3"><label class="form-label">Kategori</label><select class="form-select" name="category"><?php foreach($categories as $code=>$label):?><option value="<?=$code?>" <?=$t['category']===$code?'selected':''?>><?=$label?></option><?php endforeach?></select></div><div class="col-12"><label class="form-label">Isi pesan</label><textarea class="form-control" name="body" rows="7" required><?=html_escape($t['body'])?></textarea><div class="form-hint">Variabel tersedia: {member_name}, {member_no}, {request_code}, {book_title}, {status}, {staff_note}, {due_date}, {late_days}.</div></div><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="is_active" value="1" <?=!empty($t['is_active'])?'checked':''?>><span class="form-check-label">Template aktif</span></label></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary"><i class="ti ti-device-floppy me-1"></i>Simpan perubahan</button></div><?=form_close()?></div></div></div><?php endforeach;endif?>
</div></div>
